//! Minimal TOML reader/writer tailored for the data files used by jot.
//!
//! The reader accepts the TOML syntax we care about (tables, dotted keys,
//! strings in all four flavours, numbers, booleans, date/time literals,
//! arrays and inline tables). The writer mimics the "pretty" style used by
//! older TOML serializers: literal strings when possible, 4-space indented
//! multi-line arrays with trailing commas.

use std::collections::HashMap;
use std::fmt::Write as _;

#[derive(Debug, Clone, PartialEq)]
pub enum Value {
    Str(String),
    Int(i64),
    Float(f64),
    Bool(bool),
    Datetime(String),
    Array(Vec<Value>),
    Table(Table),
}

#[derive(Debug, Clone, PartialEq, Default)]
pub struct Table {
    pub entries: Vec<(String, Value)>,
}

impl Table {
    pub fn new() -> Self {
        Table { entries: Vec::new() }
    }

    pub fn get(&self, key: &str) -> Option<&Value> {
        self.entries.iter().find(|(k, _)| k == key).map(|(_, v)| v)
    }

    fn get_mut(&mut self, key: &str) -> Option<&mut Value> {
        self.entries.iter_mut().find(|(k, _)| k == key).map(|(_, v)| v)
    }

    pub fn insert(&mut self, key: &str, value: Value) {
        if let Some(slot) = self.get_mut(key) {
            *slot = value;
        } else {
            self.entries.push((key.to_string(), value));
        }
    }

    pub fn contains(&self, key: &str) -> bool {
        self.get(key).is_some()
    }
}

// ---------------------------------------------------------------------------
// Parsing
// ---------------------------------------------------------------------------

#[derive(Debug)]
pub struct ParseError;

type PResult<T> = Result<T, ParseError>;

/// Bookkeeping about how a table came into existence so duplicate
/// definitions can be rejected like a real TOML parser would.
#[derive(Clone, Copy, PartialEq)]
enum Origin {
    /// Created by an explicit `[header]`.
    Header,
    /// Created implicitly by a dotted key or a deeper header.
    Implicit,
    /// Created through dotted keys inside a key/value pair.
    Dotted,
    /// Inline table `{ ... }` – frozen, cannot be extended.
    Inline,
    /// Array of tables element.
    ArrayElem,
}

struct Parser<'a> {
    src: &'a [u8],
    pos: usize,
    /// Which paths were defined as tables and how.
    origins: HashMap<Vec<String>, Origin>,
    /// Paths of arrays of tables (`[[x]]`).
    table_arrays: HashMap<Vec<String>, usize>,
}

pub fn parse(src: &str) -> PResult<Table> {
    let mut p = Parser {
        src: src.as_bytes(),
        pos: 0,
        origins: HashMap::new(),
        table_arrays: HashMap::new(),
    };
    p.parse_document()
}

fn is_bare_key_char(c: u8) -> bool {
    c.is_ascii_alphanumeric() || c == b'_' || c == b'-'
}

impl<'a> Parser<'a> {
    fn peek(&self) -> Option<u8> {
        self.src.get(self.pos).copied()
    }

    fn peek_at(&self, off: usize) -> Option<u8> {
        self.src.get(self.pos + off).copied()
    }

    fn bump(&mut self) -> Option<u8> {
        let c = self.peek();
        if c.is_some() {
            self.pos += 1;
        }
        c
    }

    fn eat(&mut self, c: u8) -> bool {
        if self.peek() == Some(c) {
            self.pos += 1;
            true
        } else {
            false
        }
    }

    fn starts_with(&self, s: &[u8]) -> bool {
        self.src[self.pos..].starts_with(s)
    }

    fn skip_ws(&mut self) {
        while let Some(c) = self.peek() {
            if c == b' ' || c == b'\t' {
                self.pos += 1;
            } else {
                break;
            }
        }
    }

    fn skip_comment(&mut self) -> PResult<()> {
        if self.peek() == Some(b'#') {
            while let Some(c) = self.peek() {
                if c == b'\n' {
                    break;
                }
                if c == b'\r' && self.peek_at(1) == Some(b'\n') {
                    break;
                }
                if c < 0x20 && c != b'\t' {
                    return Err(ParseError);
                }
                if c == 0x7f {
                    return Err(ParseError);
                }
                self.pos += 1;
            }
        }
        Ok(())
    }

    /// Skip whitespace, comments and newlines.
    fn skip_ws_comments_newlines(&mut self) -> PResult<()> {
        loop {
            self.skip_ws();
            match self.peek() {
                Some(b'#') => self.skip_comment()?,
                Some(b'\n') => self.pos += 1,
                Some(b'\r') if self.peek_at(1) == Some(b'\n') => self.pos += 2,
                _ => return Ok(()),
            }
        }
    }

    /// Expects end of line (optionally preceded by whitespace and comment).
    fn expect_eol(&mut self) -> PResult<()> {
        self.skip_ws();
        self.skip_comment()?;
        match self.peek() {
            None => Ok(()),
            Some(b'\n') => {
                self.pos += 1;
                Ok(())
            }
            Some(b'\r') if self.peek_at(1) == Some(b'\n') => {
                self.pos += 2;
                Ok(())
            }
            _ => Err(ParseError),
        }
    }

    fn parse_document(&mut self) -> PResult<Table> {
        let mut root = Table::new();
        let mut current_path: Vec<String> = Vec::new();
        loop {
            self.skip_ws_comments_newlines()?;
            match self.peek() {
                None => break,
                Some(b'[') => {
                    self.pos += 1;
                    let is_array = self.eat(b'[');
                    self.skip_ws();
                    let path = self.parse_key_path()?;
                    self.skip_ws();
                    if !self.eat(b']') {
                        return Err(ParseError);
                    }
                    if is_array && !self.eat(b']') {
                        return Err(ParseError);
                    }
                    self.expect_eol()?;
                    if is_array {
                        self.define_table_array(&mut root, &path)?;
                    } else {
                        self.define_table(&mut root, &path)?;
                    }
                    current_path = path;
                }
                Some(_) => {
                    let (path, value) = self.parse_key_value()?;
                    self.expect_eol()?;
                    let table = self.resolve_table(&mut root, &current_path)?;
                    Self::insert_dotted(table, &current_path, &path, value, &mut self.origins)?;
                }
            }
        }
        Ok(root)
    }

    /// Navigate to the table designated by `path` (which must exist).
    fn resolve_table<'t>(&self, root: &'t mut Table, path: &[String]) -> PResult<&'t mut Table> {
        let mut cur = root;
        for key in path {
            let next = cur.get_mut(key).ok_or(ParseError)?;
            cur = match next {
                Value::Table(t) => t,
                Value::Array(items) => match items.last_mut() {
                    Some(Value::Table(t)) => t,
                    _ => return Err(ParseError),
                },
                _ => return Err(ParseError),
            };
        }
        Ok(cur)
    }

    fn define_table(&mut self, root: &mut Table, path: &[String]) -> PResult<()> {
        if path.is_empty() {
            return Err(ParseError);
        }
        let mut cur = root;
        let mut walked: Vec<String> = Vec::new();
        for (i, key) in path.iter().enumerate() {
            walked.push(key.clone());
            let last = i == path.len() - 1;
            let exists = cur.contains(key);
            if !exists {
                cur.insert(key, Value::Table(Table::new()));
                self.origins
                    .insert(walked.clone(), if last { Origin::Header } else { Origin::Implicit });
            } else if last {
                match self.origins.get(&walked) {
                    Some(Origin::Implicit) => {
                        self.origins.insert(walked.clone(), Origin::Header);
                    }
                    _ => return Err(ParseError),
                }
            }
            let next = cur.get_mut(key).ok_or(ParseError)?;
            cur = match next {
                Value::Table(t) => t,
                Value::Array(items) if self.table_arrays.contains_key(&walked) => match items.last_mut() {
                    Some(Value::Table(t)) => t,
                    _ => return Err(ParseError),
                },
                _ => return Err(ParseError),
            };
        }
        Ok(())
    }

    fn define_table_array(&mut self, root: &mut Table, path: &[String]) -> PResult<()> {
        if path.is_empty() {
            return Err(ParseError);
        }
        let mut cur = root;
        let mut walked: Vec<String> = Vec::new();
        for (i, key) in path.iter().enumerate() {
            walked.push(key.clone());
            let last = i == path.len() - 1;
            if last {
                if !cur.contains(key) {
                    cur.insert(key, Value::Array(vec![Value::Table(Table::new())]));
                    self.table_arrays.insert(walked.clone(), 1);
                } else {
                    if !self.table_arrays.contains_key(&walked) {
                        return Err(ParseError);
                    }
                    match cur.get_mut(key) {
                        Some(Value::Array(items)) => items.push(Value::Table(Table::new())),
                        _ => return Err(ParseError),
                    }
                }
                // Reset origins of children of previous elements: new element.
                self.origins.retain(|k, _| !(k.len() > walked.len() && k.starts_with(&walked)));
                self.origins.insert(walked.clone(), Origin::ArrayElem);
                return Ok(());
            }
            if !cur.contains(key) {
                cur.insert(key, Value::Table(Table::new()));
                self.origins.insert(walked.clone(), Origin::Implicit);
            }
            let next = cur.get_mut(key).ok_or(ParseError)?;
            cur = match next {
                Value::Table(t) => t,
                Value::Array(items) if self.table_arrays.contains_key(&walked) => match items.last_mut() {
                    Some(Value::Table(t)) => t,
                    _ => return Err(ParseError),
                },
                _ => return Err(ParseError),
            };
        }
        Ok(())
    }

    fn insert_dotted(
        table: &mut Table,
        base: &[String],
        path: &[String],
        value: Value,
        origins: &mut HashMap<Vec<String>, Origin>,
    ) -> PResult<()> {
        let mut cur = table;
        let mut walked: Vec<String> = base.to_vec();
        for key in &path[..path.len() - 1] {
            walked.push(key.clone());
            if !cur.contains(key) {
                cur.insert(key, Value::Table(Table::new()));
                origins.insert(walked.clone(), Origin::Dotted);
            } else {
                match origins.get(&walked) {
                    Some(Origin::Dotted) => {}
                    _ => return Err(ParseError),
                }
            }
            cur = match cur.get_mut(key) {
                Some(Value::Table(t)) => t,
                _ => return Err(ParseError),
            };
        }
        let last = &path[path.len() - 1];
        if cur.contains(last) {
            return Err(ParseError);
        }
        walked.push(last.clone());
        if let Value::Table(_) = value {
            origins.insert(walked, Origin::Inline);
        }
        cur.insert(last, value);
        Ok(())
    }

    fn parse_key_path(&mut self) -> PResult<Vec<String>> {
        let mut path = Vec::new();
        loop {
            self.skip_ws();
            let key = self.parse_simple_key()?;
            path.push(key);
            self.skip_ws();
            if self.eat(b'.') {
                continue;
            }
            break;
        }
        Ok(path)
    }

    fn parse_simple_key(&mut self) -> PResult<String> {
        match self.peek() {
            Some(b'"') => {
                self.pos += 1;
                self.parse_basic_string_body()
            }
            Some(b'\'') => {
                self.pos += 1;
                self.parse_literal_string_body()
            }
            Some(c) if is_bare_key_char(c) => {
                let start = self.pos;
                while let Some(c) = self.peek() {
                    if is_bare_key_char(c) {
                        self.pos += 1;
                    } else {
                        break;
                    }
                }
                Ok(String::from_utf8_lossy(&self.src[start..self.pos]).into_owned())
            }
            _ => Err(ParseError),
        }
    }

    fn parse_key_value(&mut self) -> PResult<(Vec<String>, Value)> {
        let path = self.parse_key_path()?;
        self.skip_ws();
        if !self.eat(b'=') {
            return Err(ParseError);
        }
        self.skip_ws();
        let value = self.parse_value()?;
        Ok((path, value))
    }

    fn parse_value(&mut self) -> PResult<Value> {
        match self.peek() {
            None => Err(ParseError),
            Some(b'"') => {
                if self.starts_with(b"\"\"\"") {
                    self.pos += 3;
                    self.parse_multiline_basic_string().map(Value::Str)
                } else {
                    self.pos += 1;
                    self.parse_basic_string_body().map(Value::Str)
                }
            }
            Some(b'\'') => {
                if self.starts_with(b"'''") {
                    self.pos += 3;
                    self.parse_multiline_literal_string().map(Value::Str)
                } else {
                    self.pos += 1;
                    self.parse_literal_string_body().map(Value::Str)
                }
            }
            Some(b'[') => self.parse_array(),
            Some(b'{') => self.parse_inline_table(),
            Some(b't') => {
                if self.starts_with(b"true") {
                    self.pos += 4;
                    Ok(Value::Bool(true))
                } else {
                    Err(ParseError)
                }
            }
            Some(b'f') => {
                if self.starts_with(b"false") {
                    self.pos += 5;
                    Ok(Value::Bool(false))
                } else {
                    Err(ParseError)
                }
            }
            Some(_) => self.parse_number_or_datetime(),
        }
    }

    fn parse_array(&mut self) -> PResult<Value> {
        // assumes current char is '['
        self.pos += 1;
        let mut items = Vec::new();
        loop {
            self.skip_ws_comments_newlines()?;
            if self.eat(b']') {
                break;
            }
            let v = self.parse_value()?;
            items.push(v);
            self.skip_ws_comments_newlines()?;
            if self.eat(b',') {
                continue;
            }
            self.skip_ws_comments_newlines()?;
            if self.eat(b']') {
                break;
            }
            return Err(ParseError);
        }
        Ok(Value::Array(items))
    }

    fn parse_inline_table(&mut self) -> PResult<Value> {
        self.pos += 1;
        let mut table = Table::new();
        let mut origins: HashMap<Vec<String>, Origin> = HashMap::new();
        self.skip_ws();
        if self.eat(b'}') {
            return Ok(Value::Table(table));
        }
        loop {
            self.skip_ws();
            let (path, value) = self.parse_key_value()?;
            Self::insert_dotted(&mut table, &[], &path, value, &mut origins)?;
            self.skip_ws();
            if self.eat(b',') {
                continue;
            }
            if self.eat(b'}') {
                break;
            }
            return Err(ParseError);
        }
        Ok(Value::Table(table))
    }

    fn parse_escape(&mut self, out: &mut String) -> PResult<()> {
        // after backslash
        match self.bump() {
            Some(b'b') => out.push('\u{8}'),
            Some(b't') => out.push('\t'),
            Some(b'n') => out.push('\n'),
            Some(b'f') => out.push('\u{c}'),
            Some(b'r') => out.push('\r'),
            Some(b'"') => out.push('"'),
            Some(b'\\') => out.push('\\'),
            Some(b'u') => {
                let cp = self.parse_hex(4)?;
                out.push(char::from_u32(cp).ok_or(ParseError)?);
            }
            Some(b'U') => {
                let cp = self.parse_hex(8)?;
                out.push(char::from_u32(cp).ok_or(ParseError)?);
            }
            _ => return Err(ParseError),
        }
        Ok(())
    }

    fn parse_hex(&mut self, n: usize) -> PResult<u32> {
        let mut v: u32 = 0;
        for _ in 0..n {
            let c = self.bump().ok_or(ParseError)?;
            let d = (c as char).to_digit(16).ok_or(ParseError)?;
            v = v.checked_mul(16).ok_or(ParseError)? + d;
        }
        Ok(v)
    }

    fn take_utf8_char(&mut self, out: &mut String) -> PResult<()> {
        let rest = &self.src[self.pos..];
        let s = std::str::from_utf8(&rest[..rest.len().min(4)])
            .or_else(|e| std::str::from_utf8(&rest[..e.valid_up_to()]))
            .map_err(|_| ParseError)?;
        let ch = s.chars().next().ok_or(ParseError)?;
        out.push(ch);
        self.pos += ch.len_utf8();
        Ok(())
    }

    fn parse_basic_string_body(&mut self) -> PResult<String> {
        let mut out = String::new();
        loop {
            match self.peek() {
                None => return Err(ParseError),
                Some(b'"') => {
                    self.pos += 1;
                    return Ok(out);
                }
                Some(b'\\') => {
                    self.pos += 1;
                    self.parse_escape(&mut out)?;
                }
                Some(b'\n') => return Err(ParseError),
                Some(c) if c < 0x20 && c != b'\t' => return Err(ParseError),
                Some(0x7f) => return Err(ParseError),
                Some(_) => self.take_utf8_char(&mut out)?,
            }
        }
    }

    fn parse_multiline_basic_string(&mut self) -> PResult<String> {
        let mut out = String::new();
        // trim first newline
        if self.eat(b'\n') {
        } else if self.starts_with(b"\r\n") {
            self.pos += 2;
        }
        loop {
            match self.peek() {
                None => return Err(ParseError),
                Some(b'"') => {
                    if self.starts_with(b"\"\"\"") {
                        self.pos += 3;
                        // up to two additional quotes may belong to the content
                        while self.peek() == Some(b'"') && out.len() < usize::MAX {
                            // allow """"" (quotes at end)
                            let mut extra = 0;
                            while self.peek() == Some(b'"') && extra < 2 {
                                out.push('"');
                                self.pos += 1;
                                extra += 1;
                            }
                            if self.peek() == Some(b'"') {
                                return Err(ParseError);
                            }
                        }
                        return Ok(out);
                    }
                    out.push('"');
                    self.pos += 1;
                }
                Some(b'\\') => {
                    self.pos += 1;
                    // line ending backslash
                    let save = self.pos;
                    self.skip_ws();
                    if self.peek() == Some(b'\n') || self.starts_with(b"\r\n") {
                        self.skip_ws_newlines_only();
                    } else {
                        self.pos = save;
                        self.parse_escape(&mut out)?;
                    }
                }
                Some(b'\r') if self.peek_at(1) == Some(b'\n') => {
                    out.push('\n');
                    self.pos += 2;
                }
                Some(b'\n') => {
                    out.push('\n');
                    self.pos += 1;
                }
                Some(c) if c < 0x20 && c != b'\t' => return Err(ParseError),
                Some(0x7f) => return Err(ParseError),
                Some(_) => self.take_utf8_char(&mut out)?,
            }
        }
    }

    fn skip_ws_newlines_only(&mut self) {
        while let Some(c) = self.peek() {
            if c == b' ' || c == b'\t' || c == b'\n' || c == b'\r' {
                self.pos += 1;
            } else {
                break;
            }
        }
    }

    fn parse_literal_string_body(&mut self) -> PResult<String> {
        let mut out = String::new();
        loop {
            match self.peek() {
                None => return Err(ParseError),
                Some(b'\'') => {
                    self.pos += 1;
                    return Ok(out);
                }
                Some(b'\n') => return Err(ParseError),
                Some(c) if c < 0x20 && c != b'\t' => return Err(ParseError),
                Some(0x7f) => return Err(ParseError),
                Some(_) => self.take_utf8_char(&mut out)?,
            }
        }
    }

    fn parse_multiline_literal_string(&mut self) -> PResult<String> {
        let mut out = String::new();
        if self.eat(b'\n') {
        } else if self.starts_with(b"\r\n") {
            self.pos += 2;
        }
        loop {
            match self.peek() {
                None => return Err(ParseError),
                Some(b'\'') => {
                    if self.starts_with(b"'''") {
                        self.pos += 3;
                        let mut extra = 0;
                        while self.peek() == Some(b'\'') && extra < 2 {
                            out.push('\'');
                            self.pos += 1;
                            extra += 1;
                        }
                        if self.peek() == Some(b'\'') {
                            return Err(ParseError);
                        }
                        return Ok(out);
                    }
                    out.push('\'');
                    self.pos += 1;
                }
                Some(b'\r') if self.peek_at(1) == Some(b'\n') => {
                    out.push('\n');
                    self.pos += 2;
                }
                Some(b'\n') => {
                    out.push('\n');
                    self.pos += 1;
                }
                Some(c) if c < 0x20 && c != b'\t' => return Err(ParseError),
                Some(0x7f) => return Err(ParseError),
                Some(_) => self.take_utf8_char(&mut out)?,
            }
        }
    }

    fn parse_number_or_datetime(&mut self) -> PResult<Value> {
        // Collect the token: chars allowed in numbers / datetimes.
        let start = self.pos;
        let mut saw_space_in_datetime = false;
        while let Some(c) = self.peek() {
            let ok = c.is_ascii_alphanumeric()
                || c == b'_'
                || c == b'+'
                || c == b'-'
                || c == b'.'
                || c == b':';
            if ok {
                self.pos += 1;
            } else if c == b' '
                && !saw_space_in_datetime
                && self.pos - start == 10
                && self.src[start..self.pos].iter().filter(|&&b| b == b'-').count() == 2
                && self.peek_at(1).map_or(false, |d| d.is_ascii_digit())
            {
                // local date followed by time separated by a space
                saw_space_in_datetime = true;
                self.pos += 1;
            } else {
                break;
            }
        }
        let tok = std::str::from_utf8(&self.src[start..self.pos]).map_err(|_| ParseError)?;
        if tok.is_empty() {
            return Err(ParseError);
        }
        if let Some(v) = parse_integer(tok) {
            return Ok(Value::Int(v));
        }
        if let Some(v) = parse_float(tok) {
            return Ok(Value::Float(v));
        }
        if looks_like_datetime(tok) {
            return Ok(Value::Datetime(tok.to_string()));
        }
        Err(ParseError)
    }
}

fn strip_underscores(s: &str) -> Option<String> {
    // underscores must be between digits
    let bytes = s.as_bytes();
    let mut out = String::with_capacity(s.len());
    for (i, &b) in bytes.iter().enumerate() {
        if b == b'_' {
            let prev = i.checked_sub(1).map(|j| bytes[j]);
            let next = bytes.get(i + 1).copied();
            match (prev, next) {
                (Some(p), Some(n)) if p.is_ascii_alphanumeric() && n.is_ascii_alphanumeric() => {}
                _ => return None,
            }
        } else {
            out.push(b as char);
        }
    }
    Some(out)
}

fn parse_integer(tok: &str) -> Option<i64> {
    let (neg, body) = match tok.as_bytes().first()? {
        b'+' => (false, &tok[1..]),
        b'-' => (true, &tok[1..]),
        _ => (false, tok),
    };
    if body.is_empty() {
        return None;
    }
    if let Some(rest) = body.strip_prefix("0x") {
        if neg || tok.starts_with('+') {
            return None;
        }
        let digits = strip_underscores(rest)?;
        if digits.is_empty() || !digits.bytes().all(|b| b.is_ascii_hexdigit()) {
            return None;
        }
        return i64::from_str_radix(&digits, 16).ok();
    }
    if let Some(rest) = body.strip_prefix("0o") {
        if neg || tok.starts_with('+') {
            return None;
        }
        let digits = strip_underscores(rest)?;
        if digits.is_empty() || !digits.bytes().all(|b| (b'0'..=b'7').contains(&b)) {
            return None;
        }
        return i64::from_str_radix(&digits, 8).ok();
    }
    if let Some(rest) = body.strip_prefix("0b") {
        if neg || tok.starts_with('+') {
            return None;
        }
        let digits = strip_underscores(rest)?;
        if digits.is_empty() || !digits.bytes().all(|b| b == b'0' || b == b'1') {
            return None;
        }
        return i64::from_str_radix(&digits, 2).ok();
    }
    let digits = strip_underscores(body)?;
    if digits.is_empty() || !digits.bytes().all(|b| b.is_ascii_digit()) {
        return None;
    }
    if digits.len() > 1 && digits.starts_with('0') {
        return None;
    }
    let v: i64 = digits.parse().ok()?;
    Some(if neg { -v } else { v })
}

fn parse_float(tok: &str) -> Option<f64> {
    let (neg, body) = match tok.as_bytes().first()? {
        b'+' => (false, &tok[1..]),
        b'-' => (true, &tok[1..]),
        _ => (false, tok),
    };
    match body {
        "inf" => return Some(if neg { f64::NEG_INFINITY } else { f64::INFINITY }),
        "nan" => return Some(f64::NAN),
        _ => {}
    }
    let cleaned = strip_underscores(body)?;
    if cleaned.is_empty() {
        return None;
    }
    // must contain '.' or 'e'/'E'
    if !cleaned.contains('.') && !cleaned.contains('e') && !cleaned.contains('E') {
        return None;
    }
    // validate shape: digits [. digits] [e [+-] digits]
    let bytes = cleaned.as_bytes();
    let mut i = 0;
    let mut int_digits = 0;
    while i < bytes.len() && bytes[i].is_ascii_digit() {
        i += 1;
        int_digits += 1;
    }
    if int_digits == 0 {
        return None;
    }
    if int_digits > 1 && bytes[0] == b'0' {
        return None;
    }
    if i < bytes.len() && bytes[i] == b'.' {
        i += 1;
        let mut frac = 0;
        while i < bytes.len() && bytes[i].is_ascii_digit() {
            i += 1;
            frac += 1;
        }
        if frac == 0 {
            return None;
        }
    }
    if i < bytes.len() && (bytes[i] == b'e' || bytes[i] == b'E') {
        i += 1;
        if i < bytes.len() && (bytes[i] == b'+' || bytes[i] == b'-') {
            i += 1;
        }
        let mut exp = 0;
        while i < bytes.len() && bytes[i].is_ascii_digit() {
            i += 1;
            exp += 1;
        }
        if exp == 0 {
            return None;
        }
    }
    if i != bytes.len() {
        return None;
    }
    let v: f64 = cleaned.parse().ok()?;
    Some(if neg { -v } else { v })
}

fn looks_like_datetime(tok: &str) -> bool {
    let b = tok.as_bytes();
    let digits = |r: std::ops::Range<usize>| r.end <= b.len() && b[r].iter().all(|c| c.is_ascii_digit());
    // local time HH:MM:SS[.frac]
    let is_time = |s: &[u8]| -> bool {
        if s.len() < 8 {
            return false;
        }
        let ok = s[0].is_ascii_digit()
            && s[1].is_ascii_digit()
            && s[2] == b':'
            && s[3].is_ascii_digit()
            && s[4].is_ascii_digit()
            && s[5] == b':'
            && s[6].is_ascii_digit()
            && s[7].is_ascii_digit();
        if !ok {
            return false;
        }
        let rest = &s[8..];
        if rest.is_empty() {
            return true;
        }
        if rest[0] == b'.' {
            return rest.len() > 1 && rest[1..].iter().all(|c| c.is_ascii_digit());
        }
        false
    };
    if digits(0..4) && b.len() >= 10 && b[4] == b'-' && digits(5..7) && b[7] == b'-' && digits(8..10) {
        if b.len() == 10 {
            return true;
        }
        if b[10] != b'T' && b[10] != b't' && b[10] != b' ' {
            return false;
        }
        let rest = &b[11..];
        // split off offset
        let (time, offset) = if let Some(p) = rest.iter().position(|&c| c == b'Z' || c == b'z' || c == b'+') {
            (&rest[..p], &rest[p..])
        } else if let Some(p) = rest.iter().rposition(|&c| c == b'-') {
            (&rest[..p], &rest[p..])
        } else {
            (rest, &rest[rest.len()..])
        };
        if !is_time(time) {
            return false;
        }
        if offset.is_empty() {
            return true;
        }
        if offset == b"Z" || offset == b"z" {
            return true;
        }
        return offset.len() == 6
            && (offset[0] == b'+' || offset[0] == b'-')
            && offset[1].is_ascii_digit()
            && offset[2].is_ascii_digit()
            && offset[3] == b':'
            && offset[4].is_ascii_digit()
            && offset[5].is_ascii_digit();
    }
    is_time(b)
}

// ---------------------------------------------------------------------------
// Serialization ("pretty" style)
// ---------------------------------------------------------------------------

fn key_needs_quotes(key: &str) -> bool {
    key.is_empty() || !key.bytes().all(is_bare_key_char)
}

fn write_std_string(out: &mut String, value: &str, multiline: bool) {
    if multiline {
        out.push_str("\"\"\"\n");
    } else {
        out.push('"');
    }
    for ch in value.chars() {
        match ch {
            '\u{8}' => out.push_str("\\b"),
            '\u{9}' => out.push_str("\\t"),
            '\u{a}' => {
                if multiline {
                    out.push('\n');
                } else {
                    out.push_str("\\n");
                }
            }
            '\u{c}' => out.push_str("\\f"),
            '\u{d}' => out.push_str("\\r"),
            '\u{22}' => out.push_str("\\\""),
            '\u{5c}' => out.push_str("\\\\"),
            c if c <= '\u{1f}' || c == '\u{7f}' => {
                let _ = write!(out, "\\u{:04X}", ch as u32);
            }
            ch => out.push(ch),
        }
    }
    if multiline {
        out.push_str("\"\"\"");
    } else {
        out.push('"');
    }
}

fn write_key(out: &mut String, key: &str) {
    if key_needs_quotes(key) {
        write_std_string(out, key, false);
    } else {
        out.push_str(key);
    }
}

/// Write a string value preferring literal strings.
fn write_string_value(out: &mut String, value: &str) {
    #[derive(PartialEq)]
    enum Kind {
        NewlineTriple,
        OnelineTriple,
        OnelineSingle,
    }
    let mut ty = Kind::OnelineSingle;
    let mut max_found_singles = 0;
    let mut found_singles = 0;
    let mut can_be_pretty = true;
    for ch in value.chars() {
        if can_be_pretty {
            if ch == '\'' {
                found_singles += 1;
                if found_singles >= 3 {
                    can_be_pretty = false;
                }
            } else {
                if found_singles > max_found_singles {
                    max_found_singles = found_singles;
                }
                found_singles = 0;
            }
            match ch {
                '\t' => {}
                '\n' => ty = Kind::NewlineTriple,
                c if c <= '\u{1f}' || c == '\u{7f}' => can_be_pretty = false,
                _ => {}
            }
        } else if ch == '\n' {
            ty = Kind::NewlineTriple;
        }
    }
    if can_be_pretty && found_singles > 0 && value.ends_with('\'') {
        can_be_pretty = false;
    }
    if !can_be_pretty {
        write_std_string(out, value, ty == Kind::NewlineTriple);
        return;
    }
    if found_singles > max_found_singles {
        max_found_singles = found_singles;
    }
    if ty == Kind::OnelineSingle && max_found_singles >= 1 {
        ty = Kind::OnelineTriple;
    }
    match ty {
        Kind::NewlineTriple => out.push_str("'''\n"),
        Kind::OnelineTriple => out.push_str("'''"),
        Kind::OnelineSingle => out.push('\''),
    }
    out.push_str(value);
    match ty {
        Kind::OnelineSingle => out.push('\''),
        _ => out.push_str("'''"),
    }
}

fn write_float(out: &mut String, v: f64) {
    if v.is_nan() {
        out.push_str("nan");
    } else if v.is_infinite() {
        if v < 0.0 {
            out.push_str("-inf");
        } else {
            out.push_str("inf");
        }
    } else if v.fract() == 0.0 && v.abs() < 1e16 {
        let _ = write!(out, "{:.1}", v);
    } else {
        let _ = write!(out, "{}", v);
    }
}

fn write_inline_value(out: &mut String, value: &Value) {
    match value {
        Value::Str(s) => write_string_value(out, s),
        Value::Int(i) => {
            let _ = write!(out, "{}", i);
        }
        Value::Float(f) => write_float(out, *f),
        Value::Bool(b) => {
            let _ = write!(out, "{}", b);
        }
        Value::Datetime(d) => out.push_str(d),
        Value::Array(items) => write_array(out, items),
        Value::Table(t) => {
            out.push('{');
            let mut first = true;
            for (k, v) in &t.entries {
                if !first {
                    out.push(',');
                }
                first = false;
                out.push(' ');
                write_key(out, k);
                out.push_str(" = ");
                write_inline_value(out, v);
            }
            if !first {
                out.push(' ');
            }
            out.push('}');
        }
    }
}

fn write_array(out: &mut String, items: &[Value]) {
    if items.is_empty() {
        out.push_str("[]");
        return;
    }
    let pretty = items.len() > 1;
    for (i, item) in items.iter().enumerate() {
        if pretty {
            if i == 0 {
                out.push_str("[\n");
            } else {
                out.push_str(",\n");
            }
            out.push_str("    ");
        } else if i == 0 {
            out.push('[');
        } else {
            out.push_str(", ");
        }
        write_inline_value(out, item);
    }
    if pretty {
        out.push_str(",\n]");
    } else {
        out.push(']');
    }
}

/// Serialize a table as a TOML document. Plain values are emitted first and
/// sub tables afterwards with `[header]` lines.
pub fn to_string(table: &Table) -> String {
    let mut out = String::new();
    let mut emitted_anything = false;
    write_table(&mut out, table, &[], &mut emitted_anything);
    out
}

fn write_table(out: &mut String, table: &Table, path: &[String], emitted_anything: &mut bool) {
    for (k, v) in &table.entries {
        if let Value::Table(_) = v {
            continue;
        }
        if let Value::Array(items) = v {
            if !items.is_empty() && items.iter().all(|i| matches!(i, Value::Table(_))) {
                continue;
            }
        }
        write_key(out, k);
        out.push_str(" = ");
        write_inline_value(out, v);
        out.push('\n');
        *emitted_anything = true;
    }
    for (k, v) in &table.entries {
        let mut sub_path = path.to_vec();
        sub_path.push(k.clone());
        match v {
            Value::Table(t) => {
                if *emitted_anything {
                    out.push('\n');
                }
                out.push('[');
                write_path(out, &sub_path);
                out.push_str("]\n");
                *emitted_anything = true;
                write_table(out, t, &sub_path, emitted_anything);
            }
            Value::Array(items) if !items.is_empty() && items.iter().all(|i| matches!(i, Value::Table(_))) => {
                for item in items {
                    if let Value::Table(t) = item {
                        if *emitted_anything {
                            out.push('\n');
                        }
                        out.push_str("[[");
                        write_path(out, &sub_path);
                        out.push_str("]]\n");
                        *emitted_anything = true;
                        write_table(out, t, &sub_path, emitted_anything);
                    }
                }
            }
            _ => {}
        }
    }
}

fn write_path(out: &mut String, path: &[String]) {
    for (i, p) in path.iter().enumerate() {
        if i > 0 {
            out.push('.');
        }
        write_key(out, p);
    }
}
