//! User configuration (`<config dir>/jot/config`).

use std::path::PathBuf;

use crate::toml::{Table, Value};
use crate::traits::FileIO;

/// Names of the configurable items.
pub const CONFIG_TYPES: &[&str] = &["editor", "conflict"];

#[derive(Debug, Clone)]
pub struct Config {
    pub editor: String,
    pub conflict: bool,
}

impl FileIO for Config {
    fn from_table(table: &Table) -> Option<Self> {
        let editor = match table.get("editor")? {
            Value::Str(s) => s.clone(),
            _ => return None,
        };
        let conflict = match table.get("conflict")? {
            Value::Bool(b) => *b,
            _ => return None,
        };
        Some(Config { editor, conflict })
    }

    fn to_table(&self) -> Table {
        let mut table = Table::new();
        table.insert("editor", Value::Str(self.editor.clone()));
        table.insert("conflict", Value::Bool(self.conflict));
        table
    }

    fn default_value() -> Self {
        Config {
            editor: "nvim".to_string(),
            conflict: true,
        }
    }
}

impl Config {
    /// Location of the configuration file.
    pub fn path() -> PathBuf {
        crate::dirs::config_dir().join("jot").join("config")
    }

    /// Load the configuration, creating the default one if needed.
    pub fn load() -> Self {
        <Self as FileIO>::load(&Self::path())
    }

    /// Persist the configuration.
    pub fn store(&self) {
        <Self as FileIO>::store(self, &Self::path())
    }

    /// Textual value of a configuration item.
    pub fn get(&self, config_type: &str) -> String {
        match config_type {
            "editor" => self.editor.clone(),
            "conflict" => self.conflict.to_string(),
            _ => String::new(),
        }
    }

    /// Update a configuration item from its textual representation.
    pub fn set(&mut self, config_type: &str, newvalue: &str) {
        match config_type {
            "editor" => self.editor = newvalue.to_string(),
            "conflict" => {
                self.conflict = newvalue.parse().unwrap();
            }
            _ => {}
        }
    }
}
