//! Lookup of the user's configuration and data directories following the
//! XDG base directory specification.

use std::env;
use std::path::PathBuf;

fn absolute_env_path(name: &str) -> Option<PathBuf> {
    let value = env::var_os(name)?;
    let path = PathBuf::from(value);
    if path.is_absolute() {
        Some(path)
    } else {
        None
    }
}

fn home_dir() -> PathBuf {
    #[allow(deprecated)]
    env::home_dir().unwrap()
}

/// `$XDG_CONFIG_HOME` or `$HOME/.config`.
pub fn config_dir() -> PathBuf {
    absolute_env_path("XDG_CONFIG_HOME").unwrap_or_else(|| home_dir().join(".config"))
}

/// `$XDG_DATA_HOME` or `$HOME/.local/share`.
pub fn data_dir() -> PathBuf {
    absolute_env_path("XDG_DATA_HOME").unwrap_or_else(|| home_dir().join(".local").join("share"))
}
