//! Copy-then-delete style move operations for files and folders, able to
//! cross file system boundaries.

use std::fs;
use std::io;
use std::path::{Path, PathBuf};

#[derive(Debug)]
pub struct Error {
    pub message: String,
}

impl Error {
    fn new(message: impl Into<String>) -> Self {
        Error {
            message: message.into(),
        }
    }
}

impl From<io::Error> for Error {
    fn from(err: io::Error) -> Self {
        match err.kind() {
            io::ErrorKind::NotFound
            | io::ErrorKind::PermissionDenied
            | io::ErrorKind::AlreadyExists
            | io::ErrorKind::Interrupted
            | io::ErrorKind::Other => Error::new(err.to_string()),
            _ => Error::new("Io error. Look inside for more details"),
        }
    }
}

impl From<std::path::StripPrefixError> for Error {
    fn from(_: std::path::StripPrefixError) -> Self {
        Error::new("StripPrefixError. Look inside for more details")
    }
}

pub type Result<T> = std::result::Result<T, Error>;

fn path_msg(path: &Path, with_path: &str, without_path: &str) -> String {
    match path.to_str() {
        Some(p) => with_path.replace("{}", p),
        None => without_path.to_string(),
    }
}

/// Total size of a file or folder (following symlinks).
fn get_size(path: &Path) -> Result<u64> {
    let mut result = 0;
    if path.is_dir() {
        for entry in fs::read_dir(path)? {
            let entry_path = entry?.path();
            if entry_path.is_file() {
                result += entry_path.metadata()?.len();
            } else {
                result += get_size(&entry_path)?;
            }
        }
    } else {
        result = path.metadata()?.len();
    }
    Ok(result)
}

struct DirContent {
    directories: Vec<String>,
    files: Vec<String>,
}

fn get_dir_content(path: &Path) -> Result<DirContent> {
    let mut directories = Vec::new();
    let mut files = Vec::new();
    let item = match path.to_str() {
        Some(s) => s.to_string(),
        None => return Err(Error::new("Invalid path")),
    };
    if path.is_dir() {
        directories.push(item);
        for entry in fs::read_dir(path)? {
            let entry_path = entry?.path();
            let mut items = get_dir_content(&entry_path)?;
            files.append(&mut items.files);
            directories.append(&mut items.directories);
        }
    } else {
        path.metadata()?;
        files.push(item);
    }
    Ok(DirContent { directories, files })
}

fn copy_file(from: &Path, to: &Path) -> Result<u64> {
    if !from.exists() {
        return Err(Error::new(path_msg(
            from,
            "Path \"{}\" does not exist or you don't have access!",
            "Path does not exist Or you don't have access!",
        )));
    }
    if !from.is_file() {
        return Err(Error::new(path_msg(
            from,
            "Path \"{}\" is not a file!",
            "Path is not a file!",
        )));
    }
    if to.exists() {
        if let Some(msg) = to.to_str() {
            return Err(Error::new(format!("Path \"{}\" is exist", msg)));
        }
    }
    Ok(fs::copy(from, to)?)
}

fn remove_file(path: &Path) -> Result<()> {
    if path.exists() {
        fs::remove_file(path)?;
    }
    Ok(())
}

fn remove_dir(path: &Path) -> Result<()> {
    if path.exists() {
        fs::remove_dir_all(path)?;
    }
    Ok(())
}

fn move_file(from: &Path, to: &Path) -> Result<u64> {
    let result = copy_file(from, to)?;
    remove_file(from)?;
    Ok(result)
}

fn move_dir(from: &Path, to: &Path) -> Result<u64> {
    if !from.exists() {
        return Err(Error::new(path_msg(
            from,
            "Path \"{}\" does not exist or you don't have access!",
            "Path does not exist or you don't have access!",
        )));
    }
    if !from.is_dir() {
        return Err(Error::new(path_msg(
            from,
            "Path \"{}\" is not a directory!",
            "Path is not a directory!",
        )));
    }
    let dir_name = match from.components().last() {
        Some(component) => component.as_os_str().to_os_string(),
        None => return Err(Error::new("Invalid folder from")),
    };
    let mut to: PathBuf = to.to_path_buf();
    to.push(dir_name);

    let content = get_dir_content(from)?;
    for directory in &content.directories {
        let relative = Path::new(directory).strip_prefix(from)?;
        let dir = to.join(relative);
        if !dir.exists() {
            fs::create_dir(&dir)?;
        }
    }
    let mut result = 0;
    for file in &content.files {
        let relative = Path::new(file).strip_prefix(from)?;
        let path = to.join(relative);
        result += move_file(Path::new(file), &path)?;
    }
    remove_dir(from)?;
    Ok(result)
}

/// Move every item of `from_items` inside the folder `to`.
pub fn move_items(from_items: &[PathBuf], to: &Path) -> Result<u64> {
    for item in from_items {
        get_size(item)?;
    }
    let mut result = 0;
    for item in from_items {
        if item.is_dir() {
            result += move_dir(item, to)?;
        } else {
            match item.file_name() {
                Some(file_name) => {
                    result += move_file(item, &to.join(file_name))?;
                }
                None => return Err(Error::new("Invalid file name")),
            }
        }
    }
    Ok(result)
}
