    SameName,
    InvalidName,
    ItemExists(ItemType, String),
    ItemNotFound(&'static str, String),
    EditorNotFound,
    Undefined(io::Error),
    Fs(String),
}

impl fmt::Display for Error {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Error::NotInsideVault => write!(f, "not inside a vault"),
            Error::VaultNotFound(name) => write!(f, "vault {} doesn't exist", name),
            Error::VaultExists(name) => write!(f, "vault {} already exists", name),
            Error::AlreadyInVault(name) => write!(f, "already in vault {}", name),
            Error::PathNotFound => write!(f, "couldn't find the path specified"),
            Error::PathNotAbsolute => write!(f, "specified path isn't absolute"),
            Error::OutOfBounds => write!(f, "path crosses the bounds of vault"),
            Error::SameLocation => write!(f, "new location is same as old location"),
            Error::SameName => write!(f, "new name is same as old name"),
            Error::InvalidName => write!(f, "invalid name"),
            Error::ItemExists(item_type, name) => write!(
                f,
                "a {} named {} already exists in this location",
                item_type.label(),
