    for (i, (name, is_note)) in items.into_iter().enumerate() {
        let connector = if i + 1 == count { LAST_BRANCH } else { BRANCH };
        if is_note {
            println!("{} {}", connector, blue(&name));
        } else {
            println!("{} {}", connector, name);
        }
    }
}

/// Recursively print everything inside `path` as a tree.
pub fn list_tree(path: &Path, prefix: &str) {
    let entries: Vec<_> = fs::read_dir(path).unwrap().collect();
    let count = entries.len();
    for (i, entry) in entries.into_iter().enumerate() {
