const TRY_HELP: &str = "\n\nFor more information try --help\n";

/// Banner and overview printed for the top level help.
fn main_help() -> String {
    let b = |s: &str| blue(s);
    let mut out = String::new();
    out.push_str("\x1b[0;34m________      _____ \n");
    out.push_str("______(_)_______  /_\n");
    out.push_str("_____  /_  __ \\  __/\n");
    out.push_str("____  / / /_/ / /_  \n");
    out.push_str("___  /  \\____/\\__/  \n");
    out.push_str("/___/         ᵥ₀.₁.₂  \n");
    out.push_str("\x1b[0m         \n");
    out.push('\n');
    out.push_str("usage: jt <command>\n");
    out.push('\n');
    out.push_str(&format!("{}\n", b("commands:")));
    out.push('\n');
    out.push_str("create items\n");
    out.push_str(&format!("    {}, {}       create a vault or list vaults\n", b("vault"), b("vl")));
    out.push_str("    create items in current folder\n");
    out.push_str(&format!("        {}, {}        create a note \n", b("note"), b("nt")));
    out.push_str(&format!("        {}, {}      create a folder\n", b("folder"), b("fd")));
    out.push('\n');
    out.push_str("interact with items\n");
    out.push_str(&format!("    {}, {}       enter a vault\n", b("enter"), b("en")));
    out.push_str(&format!("    {}, {}        open a note from current folder\n", b("open"), b("op")));
    out.push_str(&format!("    {}, {}       open current folder in file explorer\n", b("opdir"), b("od")));
    out.push_str(&format!("    {}, {}       change folder within current vault\n", b("chdir"), b("cd")));
    out.push_str(&format!("    {}, {}        list items in current folder\n", b("list"), b("ls")));
    out.push('\n');
    out.push_str("perform fs operations on items\n");
    out.push_str(&format!("    {}, {}      remove an item \n", b("remove"), b("rm")));
    out.push_str(&format!("    {}, {}      rename an item \n", b("rename"), b("rn")));
    out.push_str(&format!("    {}, {}        move an item to a new location\n", b("move"), b("mv")));
    out.push_str(&format!("    {}, {}       move an item to a different vault\n", b("vmove"), b("vm")));
    out.push('\n');
