fn main_usage(bin: &str) -> String {
    format!("USAGE:\n    {} <SUBCOMMAND>", bin)
}

fn sub_usage(bin: &str, spec: &SubSpec) -> String {
    match spec.usage {
        Some(custom) => format!("USAGE:\n    {}", custom),
        None => {
            let mut line = format!("{} {}", bin, spec.name);
            for arg in spec.args {
                if arg.required {
                    line.push_str(&format!(" <{}>", arg.name));
                } else {
                    line.push_str(&format!(" [{}]", arg.name));
                }
            }
            format!("USAGE:\n    {}", line)
        }
    }
}

fn sub_help(bin: &str, spec: &SubSpec) -> String {
    let mut out = format!("{}-{} \n{}\n\n{}\n\n", bin, spec.name, spec.about, sub_usage(bin, spec));
    if !spec.args.is_empty() {
        out.push_str("ARGS:\n");
        out.push_str(spec.args_help);
        out.push('\n');
    }
    out.push_str("OPTIONS:\n");
    if spec.list_flag {
        out.push_str("    -l            show vaults' location\n");
    }
    out.push_str("    -h, --help    Print help information\n");
    out
}

fn find_sub(name: &str) -> Option<&'static SubSpec> {
    SUBCOMMANDS
        .iter()
        .find(|s| s.name == name || s.aliases.contains(&name))
}

fn all_sub_names() -> Vec<&'static str> {
    let mut names = Vec::new();
    for s in SUBCOMMANDS {
        names.push(s.name);
        names.extend_from_slice(s.aliases);
    }
    names
}

// ---------------------------------------------------------------------------
// String similarity used for suggestions.
// ---------------------------------------------------------------------------

fn jaro(a: &str, b: &str) -> f64 {
    let a_chars: Vec<char> = a.chars().collect();
    let b_chars: Vec<char> = b.chars().collect();
    let a_len = a_chars.len();
    let b_len = b_chars.len();
    if a_len == 0 && b_len == 0 {
        return 1.0;
    } else if a_len == 0 || b_len == 0 {
        return 0.0;
    } else if a_len == 1 && b_len == 1 {
        return if a_chars[0] == b_chars[0] { 1.0 } else { 0.0 };
    }
    let search_range = (a_len.max(b_len) / 2) - 1;
    let mut b_consumed = vec![false; b_len];
    let mut matches = 0.0;
    let mut transpositions = 0.0;
    let mut b_match_index = 0;
    for (i, a_elem) in a_chars.iter().enumerate() {
        let min_bound = if i > search_range { i - search_range } else { 0 };
        let max_bound = (b_len - 1).min(i + search_range);
        if min_bound > max_bound {
            continue;
        }
        for (j, b_elem) in b_chars.iter().enumerate() {
            if min_bound <= j && j <= max_bound && a_elem == b_elem && !b_consumed[j] {
                b_consumed[j] = true;
                matches += 1.0;
                if j < b_match_index {
                    transpositions += 1.0;
                }
                b_match_index = j;
                break;
            }
        }
    }
    if matches == 0.0 {
        0.0
    } else {
        (1.0 / 3.0)
            * ((matches / a_len as f64) + (matches / b_len as f64) + ((matches - transpositions) / matches))
    }
}

fn jaro_winkler(a: &str, b: &str) -> f64 {
    let jaro_distance = jaro(a, b);
    let prefix_length = a.chars().zip(b.chars()).take_while(|(x, y)| x == y).count();
    let distance = jaro_distance + (0.1 * prefix_length as f64 * (1.0 - jaro_distance));
    if distance <= 1.0 {
        distance
    } else {
        1.0
    }
}

/// Candidates similar to `value`, least similar first.
fn did_you_mean<'a>(value: &str, candidates: impl IntoIterator<Item = &'a str>) -> Vec<String> {
    let mut scored: Vec<(f64, String)> = candidates
        .into_iter()
        .map(|c| (jaro_winkler(value, c), c.to_string()))
        .filter(|(confidence, _)| *confidence > 0.8)
        .collect();
    scored.sort_by(|a, b| a.0.partial_cmp(&b.0).unwrap());
    scored.into_iter().map(|(_, c)| c).collect()
}

// ---------------------------------------------------------------------------
// Error reporting
// ---------------------------------------------------------------------------

fn fail(message: &str, usage: Option<&str>) -> ! {
    let mut out = format!("error: {}", message);
    if let Some(usage) = usage {
        out.push_str("\n\n");
        out.push_str(usage);
    }
    out.push_str(TRY_HELP);
    eprint!("{}", out);
    process::exit(2);
}

fn unknown_argument(arg: &str, usage: &str, after_double_dash: bool) -> ! {
    let mut message = format!(
        "Found argument '{}' which wasn't expected, or isn't valid in this context",
        arg
    );
    if arg.starts_with('-') {
        message.push_str(&format!(
            "\n\n\tIf you tried to supply `{}` as a value rather than a flag, use `-- {}`",
            arg, arg
        ));
    } else if after_double_dash && find_sub(arg).is_some() {
        message.push_str(&format!(
            "\n\n\tIf you tried to supply `{}` as a subcommand, remove the '--' before it.",
            arg
        ));
    }
    fail(&message, Some(usage))
}

fn invalid_value(value: &str, arg: &ArgSpec, choices: &[&str]) -> ! {
    let mut message = format!("\"{}\" isn't a valid value for '<{}>'", value, arg.name);
    message.push_str(&format!("\n\t[possible values: {}]", choices.join(", ")));
    if let Some(suggestion) = did_you_mean(value, choices.iter().copied()).pop() {
        message.push_str(&format!("\n\n\tDid you mean \"{}\"?", suggestion));
    }
    fail(&message, None)
}

fn missing_required(missing: &[&ArgSpec], usage: &str) -> ! {
    let mut message = String::from("The following required arguments were not provided:");
    for arg in missing {
        message.push_str(&format!("\n    <{}>", arg.name));
    }
    fail(&message, Some(usage))
}

fn print_help(text: &str) -> ! {
    print!("{}", text);
    process::exit(0);
}

fn lossy(arg: &OsString) -> String {
    arg.to_string_lossy().into_owned()
}

// ---------------------------------------------------------------------------
// Parsing
// ---------------------------------------------------------------------------

/// Parse the command line. Help requests and usage errors terminate the
/// process directly, exactly like a conventional argument parser would.
pub fn parse(bin: &str, args: &[OsString]) -> Command {
    let main_usage = main_usage(bin);
    let mut iter = args.iter();
    let mut after_double_dash = false;
    loop {
        let arg = match iter.next() {
            Some(arg) => arg,
            None => {
                // No subcommand given: show the overview on stderr.
                eprint!("{}", main_help());
                process::exit(2);
            }
        };
        let text = lossy(arg);
        if !after_double_dash {
            if text == "--" {
                after_double_dash = true;
                continue;
            }
            if text.starts_with('-') {
                if text == "-h" || text == "--help" {
                    print_help(&main_help());
                }
                unknown_argument(&text, &main_usage, false);
            }
            if text == "help" {
                parse_help(bin, iter.as_slice());
            }
            if let Some(spec) = find_sub(&text) {
                return parse_sub(bin, spec, iter.as_slice());
            }
            let candidates = did_you_mean(&text, all_sub_names());
            if !candidates.is_empty() {
                let quoted: Vec<String> = candidates.iter().map(|c| format!("'{}'", c)).collect();
                let message = format!(
                    "The subcommand '{}' wasn't recognized\n\n\tDid you mean {}?\n\nIf you believe you received this message in error, try re-running with '{} -- {}'",
                    text,
                    quoted.join(" or "),
                    bin,
                    text
                );
                fail(&message, Some(&main_usage));
            }
        }
        unknown_argument(&text, &main_usage, after_double_dash);
    }
}

/// `help [subcommand...]`: walk down the given subcommands and print the
/// help of the last one.
fn parse_help(bin: &str, rest: &[OsString]) -> ! {
    let mut current: Option<&SubSpec> = None;
    for arg in rest {
        let text = lossy(arg);
        let usage = match current {
            None => main_usage(bin),
            Some(spec) => sub_usage(bin, spec),
        };
        match current {
            None => match find_sub(&text) {
                Some(spec) => current = Some(spec),
                None => fail(
                    &format!("The subcommand '{}' wasn't recognized", text),
                    Some(&usage),
                ),
            },
            Some(_) => fail(
                &format!("The subcommand '{}' wasn't recognized", text),
                Some(&usage),
            ),
        }
    }
    match current {
        None => print_help(&main_help()),
        Some(spec) => print_help(&sub_help(bin, spec)),
    }
}

/// Parsed value of a positional argument.
enum Value {
    Text(String),
    Path(PathBuf),
}

fn parse_sub(bin: &str, spec: &'static SubSpec, rest: &[OsString]) -> Command {
    let usage = sub_usage(bin, spec);
    let help = sub_help(bin, spec);
    let mut values: Vec<Value> = Vec::new();
    let mut list_flag = false;
    let mut after_double_dash = false;

    for arg in rest {
        let text = lossy(arg);
        if !after_double_dash {
            if text == "--" {
                after_double_dash = true;
                continue;
            }
            if text.starts_with("--") {
                if text == "--help" {
                    print_help(&help);
                }
                unknown_argument(&text, &usage, false);
            }
            if text.starts_with('-') && text.len() > 1 {
                for flag in text[1..].chars() {
                    if flag == 'h' {
                        print_help(&help);
                    }
                    if flag == 'l' && spec.list_flag {
                        if list_flag {
                            fail(
                                "The argument '-l' was provided more than once, but cannot be used multiple times",
                                Some(&usage),
                            );
                        }
                        list_flag = true;
                        continue;
                    }
                    unknown_argument(&format!("-{}", flag), &usage, false);
                }
                continue;
            }
        }
        // Positional argument.
        let index = values.len();
        if index >= spec.args.len() {
            unknown_argument(&text, &usage, false);
        }
        let arg_spec = &spec.args[index];
        match arg_spec.kind {
            ArgKind::Path => {
                if arg.is_empty() {
                    fail(
                        &format!(
                            "The argument '<{}>' requires a value but none was supplied",
                            arg_spec.name
                        ),
                        None,
                    );
                }
                values.push(Value::Path(PathBuf::from(arg)));
            }
            ArgKind::Text => match arg.to_str() {
                Some(s) => values.push(Value::Text(s.to_string())),
                None => fail("Invalid UTF-8 was detected in one or more arguments", Some(&usage)),
            },
            ArgKind::Choice(choices) => {
                let valid = arg.to_str().map_or(false, |s| choices.contains(&s));
                if !valid {
                    invalid_value(&text, arg_spec, choices);
                }
                values.push(Value::Text(text.clone()));
            }
        }
    }

    // Required arguments.
    let mut missing: Vec<&ArgSpec> = Vec::new();
    for (i, arg_spec) in spec.args.iter().enumerate() {
        if arg_spec.required && i >= values.len() {
            missing.push(arg_spec);
        }
    }
    if spec.name == "vault" && values.len() == 1 {
        // A vault name requires a location.
        missing.push(&spec.args[1]);
    }
    if !missing.is_empty() {
        missing_required(&missing, &usage);
    }

    let mut texts = values.iter().map(|v| match v {
        Value::Text(s) => s.clone(),
        Value::Path(p) => p.to_string_lossy().into_owned(),
    });
    let mut paths = values.iter().map(|v| match v {
        Value::Text(s) => PathBuf::from(s),
        Value::Path(p) => p.clone(),
    });
    let mut text = || texts.next().unwrap_or_default();
    let mut path = || paths.next().unwrap_or_default();

    match spec.name {
        "vault" => {
            if values.is_empty() {
                Command::Vault { list: list_flag, name: None, location: None }
            } else {
                let name = text();
                let _ = text();
                let _ = path();
                let location = path();
                Command::Vault { list: list_flag, name: Some(name), location: Some(location) }
            }
        }
        "note" => Command::Note(text()),
        "folder" => Command::Folder(text()),
        "enter" => Command::Enter(text()),
        "open" => Command::Open(text()),
        "opdir" => Command::Opdir,
        "chdir" => Command::Chdir(path()),
        "list" => Command::List(if values.is_empty() { None } else { Some(text()) }),
        "remove" => Command::Remove(text(), text()),
        "rename" => Command::Rename(text(), text(), text()),
        "move" => {
            let item_type = text();
            let name = text();
            let _ = path();
            let _ = path();
            let location = path();
            Command::Move(item_type, name, location)
        }
        "vmove" => Command::Vmove(text(), text(), text()),
        "config" => {
            let config_type = if values.is_empty() { None } else { Some(text()) };
            let value = if values.len() > 1 { Some(text()) } else { None };
            Command::Config(config_type, value)
        }
        _ => {
            // `help` handled elsewhere; treat as help request.
            print_help(&help)
        }
    }
}

/// Name of the binary as shown in usage strings.
pub fn bin_name(argv0: &OsString) -> String {
    std::path::Path::new(argv0)
        .file_name()
        .and_then(|n| n.to_str())
        .filter(|n| !n.is_empty())
        .map(|n| n.to_string())
        .unwrap_or_else(|| "jt".to_string())
}
