//! Implementation of every subcommand.

use std::fs;
use std::io;
use std::path::{Path, PathBuf};
use std::process::Command as Process;

use crate::cli::Command;
use crate::fsx;
use crate::state::config::Config;
use crate::state::vaults::vault::Vault;
use crate::state::State;
use crate::utils::{self, blue, check_name, note_path, Error, ItemType, Result};

pub fn run(state: &mut State, command: Command) -> Result<()> {
    match command {
        Command::Vault { list, name, location } => match (name, location) {
            (Some(name), Some(location)) => create_vault(state, &name, &location),
            _ => {
                list_vaults(state, list);
                Ok(())
            }
        },
        Command::Note(name) => create_item(state, ItemType::Note, &name),
        Command::Folder(name) => create_item(state, ItemType::Folder, &name),
        Command::Enter(name) => enter_vault(state, &name),
        Command::Open(name) => open_note(state, &name),
        Command::Opdir => open_folder(state),
        Command::Chdir(path) => change_folder(state, &path),
        Command::List(item_type) => list(state, item_type.as_deref()),
        Command::Remove(item_type, name) => remove(state, item_type_of(&item_type), &name),
        Command::Rename(item_type, name, new_name) => {
            rename(state, item_type_of(&item_type), &name, &new_name)
        }
        Command::Move(item_type, name, location) => {
            move_item(state, item_type_of(&item_type), &name, &location)
        }
        Command::Vmove(item_type, name, vault_name) => {
            vault_move(state, item_type_of(&item_type), &name, &vault_name)
        }
        Command::Config(config_type, value) => config(state, config_type.as_deref(), value.as_deref()),
    }
}

fn item_type_of(value: &str) -> ItemType {
    ItemType::parse(value).unwrap_or(ItemType::Note)
}

/// Path of an item of the given type inside `folder`.
fn item_path(folder: &Path, item_type: ItemType, name: &str) -> PathBuf {
    match item_type {
        ItemType::Note => note_path(folder, name),
        _ => folder.join(name),
    }
}

// ---------------------------------------------------------------------------
// vault
// ---------------------------------------------------------------------------

fn list_vaults(state: &State, show_location: bool) {
    for (name, location) in &state.vaults.vaults {
        let label = if state.vaults.is_current(name) {
            format!("👉 {}", blue(name))
        } else {
            format!("   {}", name)
        };
        if show_location {
            println!("{} \t {}", label, location.display());
        } else {
            println!("{}", label);
        }
    }
}

fn create_vault(state: &mut State, name: &str, location: &Path) -> Result<()> {
    if state.vaults.contains(name) {
        return Err(Error::VaultExists(name.to_string()));
    }
    if !location.is_absolute() {
        return Err(Error::PathNotAbsolute);
    }
    if !location.exists() {
        return Err(Error::PathNotFound);
    }
    check_name(name)?;
    let location = location.canonicalize()?;
    let path = location.join(name);
    if path.exists() {
        return Err(Error::ItemExists(ItemType::Folder, name.to_string()));
    }
    fs::create_dir(&path)?;
    fs::create_dir_all(path.join(".jot"))?;
    Vault::new(name, &location).store();
    state.vaults.vaults.insert(name.to_string(), location);
    state.vaults.store();
    println!("vault {} created", blue(name));
    Ok(())
}

fn enter_vault(state: &mut State, name: &str) -> Result<()> {
    if !state.vaults.contains(name) {
        return Err(Error::VaultNotFound(name.to_string()));
    }
    if state.vaults.is_current(name) {
        return Err(Error::AlreadyInVault(name.to_string()));
    }
    state.vaults.current = Some(name.to_string());
    state.vaults.store();
    println!("entered {}", blue(name));
    Ok(())
}

// ---------------------------------------------------------------------------
// note / folder
// ---------------------------------------------------------------------------

fn create_item(state: &mut State, item_type: ItemType, name: &str) -> Result<()> {
    let vault = state.current_vault()?;
    check_name(name)?;
    let path = item_path(&vault.get_folder_path(), item_type, name);
    if path.exists() {
        return Err(Error::ItemExists(item_type, name.to_string()));
    }
    match item_type {
        ItemType::Note => {
            fs::File::create(&path)?;
        }
        _ => fs::create_dir(&path)?,
    }
    println!("{} {} created", item_type.label(), blue(name));
    Ok(())
}

fn run_editor(editor: &str, path: &Path) -> Result<()> {
    match Process::new(editor).arg(path).status() {
        Ok(_) => Ok(()),
        Err(err) if err.kind() == io::ErrorKind::NotFound => Err(Error::EditorNotFound),
        Err(err) => Err(Error::Undefined(err)),
    }
}

fn open_note(state: &mut State, name: &str) -> Result<()> {
    let editor = state.config.editor.clone();
    let vault = state.current_vault()?;
    check_name(name)?;
    let path = note_path(&vault.get_folder_path(), name);
    if !path.exists() {
        return Err(Error::ItemNotFound("note", name.to_string()));
    }
    run_editor(&editor, &path)
}

fn open_folder(state: &mut State) -> Result<()> {
    let vault = state.current_vault()?;
    let path = vault.get_folder_path();
    Process::new("xdg-open").arg(&path).spawn()?;
    Ok(())
}

/// Resolve `target` relative to the current folder of the vault and make
/// sure it stays inside the vault. Returns the folder relative to the vault
/// root.
fn resolve_folder(vault: &Vault, target: &Path) -> Result<(PathBuf, PathBuf)> {
    let path = vault.get_folder_path().join(target);
    if !path.exists() {
        return Err(Error::PathNotFound);
    }
    let canonical = path.canonicalize()?;
    let relative = match canonical.strip_prefix(vault.get_path()) {
        Ok(relative) => relative.to_path_buf(),
        Err(_) => return Err(Error::OutOfBounds),
    };
    Ok((path, relative))
}

fn change_folder(state: &mut State, target: &Path) -> Result<()> {
    let vault = state.current_vault()?;
    let (_, relative) = resolve_folder(vault, target)?;
    if relative == vault.folder {
        return Err(Error::SameLocation);
    }
    vault.folder = relative;
    vault.store();
    println!("folder changed");
    Ok(())
}

fn list(state: &mut State, item_type: Option<&str>) -> Result<()> {
    let vault = state.current_vault()?;
    let folder = vault.get_folder_path();
    utils::print_header(vault.get_name(), &vault.folder);
    match item_type.and_then(ItemType::parse) {
        None => utils::list_tree(&folder, ""),
        Some(item_type) => utils::list_items(&folder, item_type),
    }
    Ok(())
}

// ---------------------------------------------------------------------------
// remove / rename / move
// ---------------------------------------------------------------------------

fn remove(state: &mut State, item_type: ItemType, name: &str) -> Result<()> {
    if item_type == ItemType::Vault {
        if !state.vaults.contains(name) {
            return Err(Error::VaultNotFound(name.to_string()));
        }
        let path = state.vaults.path_of(name).unwrap();
        if !path.exists() {
            return Err(Error::ItemNotFound("folder", name.to_string()));
        }
        fs::remove_dir_all(&path)?;
        state.vaults.vaults.remove(name);
        if state.vaults.is_current(name) {
            state.vaults.current = None;
        }
        state.vaults.store();
        println!("vault {} removed", blue(name));
        return Ok(());
    }
    let vault = state.current_vault()?;
    check_name(name)?;
    let path = item_path(&vault.get_folder_path(), item_type, name);
    match item_type {
        ItemType::Note => {
            if !path.is_file() {
                return Err(Error::ItemNotFound("note", name.to_string()));
            }
            fs::remove_file(&path)?;
        }
        _ => {
            if !path.is_dir() {
                return Err(Error::ItemNotFound("folder", name.to_string()));
            }
            fs::remove_dir_all(&path)?;
        }
    }
    println!("{} {} removed", item_type.label(), blue(name));
    Ok(())
}

fn rename(state: &mut State, item_type: ItemType, name: &str, new_name: &str) -> Result<()> {
    if item_type == ItemType::Vault {
        if !state.vaults.contains(name) {
            return Err(Error::VaultNotFound(name.to_string()));
        }
        if state.vaults.contains(new_name) {
            return Err(Error::VaultExists(new_name.to_string()));
        }
        check_name(new_name)?;
        let location = state.vaults.location_of(name).unwrap().clone();
        let old_path = location.join(name);
        let new_path = location.join(new_name);
        if !old_path.exists() {
            return Err(Error::ItemNotFound("folder", name.to_string()));
        }
        fs::rename(&old_path, &new_path)?;
        let mut data = Vault::load(&new_path);
        data.name = Some(new_name.to_string());
        data.store();
        state.vaults.vaults.remove(name);
        state.vaults.vaults.insert(new_name.to_string(), location);
        if state.vaults.is_current(name) {
            state.vaults.current = Some(new_name.to_string());
        }
        state.vaults.store();
        println!("vault {} renamed to {}", blue(name), blue(new_name));
        return Ok(());
    }
    let vault = state.current_vault()?;
    if name == new_name {
        return Err(Error::SameName);
    }
    check_name(name)?;
    check_name(new_name)?;
    let folder = vault.get_folder_path();
    let old_path = item_path(&folder, item_type, name);
    if !old_path.exists() {
        return Err(Error::ItemNotFound(item_type.label(), name.to_string()));
    }
    fs::rename(&old_path, item_path(&folder, item_type, new_name))?;
    println!(
        "{} {} renamed to {}",
        item_type.label(),
        blue(name),
        blue(new_name)
    );
    Ok(())
}

fn move_item(state: &mut State, item_type: ItemType, name: &str, location: &Path) -> Result<()> {
    if item_type == ItemType::Vault {
        if !state.vaults.contains(name) {
            return Err(Error::VaultNotFound(name.to_string()));
        }
        if !location.is_absolute() {
            return Err(Error::PathNotAbsolute);
        }
        let old_location = state.vaults.location_of(name).unwrap().clone();
        if location == old_location {
            return Err(Error::SameLocation);
        }
        if location.join(name).exists() {
            return Err(Error::ItemExists(ItemType::Folder, name.to_string()));
        }
        fsx::move_items(&[old_location.join(name)], location)?;
        let new_location = location.canonicalize()?;
        let mut data = Vault::load(&new_location.join(name));
        data.location = Some(new_location.clone());
        data.store();
        state.vaults.vaults.insert(name.to_string(), new_location);
        state.vaults.store();
        println!("vault {} moved", blue(name));
        return Ok(());
    }
    let vault = state.current_vault()?;
    let (destination, relative) = resolve_folder(vault, location)?;
    if relative == vault.folder {
        return Err(Error::SameLocation);
    }
    check_name(name)?;
    if item_path(&destination, item_type, name).exists() {
        return Err(Error::ItemExists(item_type, name.to_string()));
    }
    let source = item_path(&vault.get_folder_path(), item_type, name);
    fsx::move_items(&[source], &destination)?;
    println!("{} {} moved", item_type.label(), blue(name));
    Ok(())
}

fn vault_move(state: &mut State, item_type: ItemType, name: &str, vault_name: &str) -> Result<()> {
    if !state.vaults.contains(vault_name) {
        return Err(Error::VaultNotFound(name.to_string()));
    }
    let destination = state.vaults.path_of(vault_name).unwrap();
    let same_vault = state.vaults.is_current(vault_name);
    let vault = state.current_vault()?;
