    let target = item_path(&destination, item_type, name);
    if target == source {
        return Err(Error::SameLocation);
    }
    check_name(name)?;
    if target.exists() {
        return Err(Error::ItemExists(item_type, name.to_string()));
    }
    fsx::move_items(&[source], &destination)?;
    println!(
        "{} {} moved to vault {}",
        item_type.label(),
        blue(name),
        blue(vault_name)
    );
    Ok(())
}

