#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Origin {
    /// Plain value or inline table.
    Value,
    /// Table created by an explicit `[header]`.
    Header,
    /// Table created implicitly by a deeper header.
    Implicit,
    /// Table created through a dotted key.
    Dotted,
    /// Element of an array of tables.
    ArrayElem,
}

#[derive(Debug, Clone, PartialEq, Default)]
pub struct Table {
    pub entries: Vec<(String, Value)>,
    origins: Vec<Origin>,
}

impl Table {
    pub fn new() -> Self {
        Table {
            entries: Vec::new(),
            origins: Vec::new(),
        }
    }

    /// First value stored under `key`.
    pub fn get(&self, key: &str) -> Option<&Value> {
        self.entries.iter().find(|(k, _)| k == key).map(|(_, v)| v)
    }

    /// Number of entries stored under `key` (duplicates are kept).
    pub fn count(&self, key: &str) -> usize {
        self.entries.iter().filter(|(k, _)| k == key).count()
    }

    /// Insert or replace a value (used when building documents).
    pub fn insert(&mut self, key: &str, value: Value) {
        if let Some(pos) = self.entries.iter().position(|(k, _)| k == key) {
            self.entries[pos].1 = value;
            self.origins[pos] = Origin::Value;
        } else {
            self.push(key, value, Origin::Value);
        }
    }

    fn push(&mut self, key: &str, value: Value, origin: Origin) {
        self.entries.push((key.to_string(), value));
        self.origins.push(origin);
    }

    fn position_first(&self, key: &str) -> Option<usize> {
        self.entries.iter().position(|(k, _)| k == key)
    }

    /// Position of the table entry created by headers for `key`.
    fn position_header(&self, key: &str) -> Option<usize> {
        self.entries.iter().enumerate().position(|(i, (k, _))| {
            k == key
                && matches!(
                    self.origins[i],
                    Origin::Header | Origin::Implicit | Origin::ArrayElem
                )
        })
    }
}

// ---------------------------------------------------------------------------
// Parsing
// ---------------------------------------------------------------------------

#[derive(Debug)]
pub struct ParseError;

type PResult<T> = Result<T, ParseError>;

struct Parser<'a> {
    src: &'a [u8],
    pos: usize,
}

pub fn parse(src: &str) -> PResult<Table> {
    let mut p = Parser {
        src: src.as_bytes(),
        pos: 0,
    };
    p.parse_document()
}

fn is_bare_key_char(c: u8) -> bool {
    c.is_ascii_alphanumeric() || c == b'_' || c == b'-'
}

/// Walk `path` through header-created tables starting at `root`, creating
/// implicit tables when needed. Returns the table for the last component.
fn descend<'t>(root: &'t mut Table, path: &[String]) -> PResult<&'t mut Table> {
    let mut cur = root;
    for key in path {
        let pos = match cur.position_header(key) {
            Some(pos) => pos,
            None => {
                cur.push(key, Value::Table(Table::new()), Origin::Implicit);
                cur.entries.len() - 1
            }
        };
        cur = match &mut cur.entries[pos].1 {
            Value::Table(t) => t,
            Value::Array(items) => match items.last_mut() {
                Some(Value::Table(t)) => t,
                _ => return Err(ParseError),
            },
            _ => return Err(ParseError),
        };
    }
    Ok(cur)
}

fn define_table(root: &mut Table, path: &[String]) -> PResult<()> {
    if path.is_empty() {
        return Err(ParseError);
    }
    let parent = descend(root, &path[..path.len() - 1])?;
    let last = &path[path.len() - 1];
    match parent.position_header(last) {
        None => parent.push(last, Value::Table(Table::new()), Origin::Header),
        Some(pos) => {
            if parent.origins[pos] != Origin::Implicit {
                return Err(ParseError);
            }
            parent.origins[pos] = Origin::Header;
        }
    }
    Ok(())
}

fn define_table_array(root: &mut Table, path: &[String]) -> PResult<()> {
    if path.is_empty() {
        return Err(ParseError);
    }
    let parent = descend(root, &path[..path.len() - 1])?;
    let last = &path[path.len() - 1];
    match parent.position_header(last) {
        None => parent.push(
            last,
            Value::Array(vec![Value::Table(Table::new())]),
            Origin::ArrayElem,
        ),
        Some(pos) => {
            if parent.origins[pos] != Origin::ArrayElem {
                return Err(ParseError);
            }
            match &mut parent.entries[pos].1 {
                Value::Array(items) => items.push(Value::Table(Table::new())),
                _ => return Err(ParseError),
            }
        }
    }
    Ok(())
}

/// Store `value` under the dotted `path` inside `table`.
fn insert_dotted(table: &mut Table, path: &[String], value: Value) -> PResult<()> {
    let mut cur = table;
    for key in &path[..path.len() - 1] {
        let pos = match cur.position_first(key) {
            Some(pos) => {
                if cur.origins[pos] != Origin::Dotted {
                    return Err(ParseError);
                }
                pos
            }
            None => {
                cur.push(key, Value::Table(Table::new()), Origin::Dotted);
                cur.entries.len() - 1
            }
        };
        cur = match &mut cur.entries[pos].1 {
            Value::Table(t) => t,
            _ => return Err(ParseError),
        };
    }
    cur.push(&path[path.len() - 1], value, Origin::Value);
    Ok(())
}

impl<'a> Parser<'a> {
    fn peek(&self) -> Option<u8> {
        self.src.get(self.pos).copied()
    }

    fn peek_at(&self, off: usize) -> Option<u8> {
        self.src.get(self.pos + off).copied()
    }

    fn bump(&mut self) -> Option<u8> {
        let c = self.peek();
        if c.is_some() {
            self.pos += 1;
        }
        c
    }

    fn eat(&mut self, c: u8) -> bool {
        if self.peek() == Some(c) {
            self.pos += 1;
            true
        } else {
            false
        }
    }

    fn starts_with(&self, s: &[u8]) -> bool {
        self.src[self.pos..].starts_with(s)
    }

    fn skip_ws(&mut self) {
        while let Some(c) = self.peek() {
            if c == b' ' || c == b'\t' {
                self.pos += 1;
            } else {
                break;
            }
        }
    }

    fn skip_comment(&mut self) -> PResult<()> {
        if self.peek() == Some(b'#') {
            while let Some(c) = self.peek() {
                if c == b'\n' {
                    break;
                }
                if c == b'\r' && self.peek_at(1) == Some(b'\n') {
                    break;
                }
                if (c < 0x20 && c != b'\t') || c == 0x7f {
                    return Err(ParseError);
                }
                self.pos += 1;
            }
        }
        Ok(())
    }

    /// Skip whitespace, comments and newlines.
    fn skip_ws_comments_newlines(&mut self) -> PResult<()> {
        loop {
            self.skip_ws();
            match self.peek() {
                Some(b'#') => self.skip_comment()?,
                Some(b'\n') => self.pos += 1,
                Some(b'\r') if self.peek_at(1) == Some(b'\n') => self.pos += 2,
                _ => return Ok(()),
            }
        }
    }

    /// Expects end of line (optionally preceded by whitespace and comment).
    fn expect_eol(&mut self) -> PResult<()> {
        self.skip_ws();
        self.skip_comment()?;
        match self.peek() {
            None => Ok(()),
            Some(b'\n') => {
                self.pos += 1;
                Ok(())
            }
            Some(b'\r') if self.peek_at(1) == Some(b'\n') => {
                self.pos += 2;
                Ok(())
            }
            _ => Err(ParseError),
        }
    }

    fn parse_document(&mut self) -> PResult<Table> {
        let mut root = Table::new();
        let mut current_path: Vec<String> = Vec::new();
        loop {
            self.skip_ws_comments_newlines()?;
            match self.peek() {
                None => break,
                Some(b'[') => {
                    self.pos += 1;
                    let is_array = self.eat(b'[');
                    self.skip_ws();
                    let path = self.parse_key_path()?;
                    self.skip_ws();
                    if !self.eat(b']') {
                        return Err(ParseError);
                    }
                    if is_array && !self.eat(b']') {
                        return Err(ParseError);
                    }
                    self.expect_eol()?;
                    if is_array {
                        define_table_array(&mut root, &path)?;
                    } else {
                        define_table(&mut root, &path)?;
                    }
                    current_path = path;
                }
                Some(_) => {
                    let (path, value) = self.parse_key_value()?;
                    self.expect_eol()?;
                    let table = descend(&mut root, &current_path)?;
                    insert_dotted(table, &path, value)?;
                }
            }
        }
        Ok(root)
    }

    fn parse_key_path(&mut self) -> PResult<Vec<String>> {
        let mut path = Vec::new();
        loop {
            self.skip_ws();
            let key = self.parse_simple_key()?;
            path.push(key);
            self.skip_ws();
            if self.eat(b'.') {
                continue;
            }
            break;
        }
        Ok(path)
    }

    fn parse_simple_key(&mut self) -> PResult<String> {
        match self.peek() {
            Some(b'"') => {
                self.pos += 1;
                self.parse_basic_string_body()
            }
            Some(b'\'') => {
                self.pos += 1;
                self.parse_literal_string_body()
            }
            Some(c) if is_bare_key_char(c) => Ok(self.take_keylike()),
            _ => Err(ParseError),
        }
    }

    /// Consume a run of bare key characters.
    fn take_keylike(&mut self) -> String {
        let start = self.pos;
        while let Some(c) = self.peek() {
            if is_bare_key_char(c) {
                self.pos += 1;
            } else {
                break;
            }
        }
        String::from_utf8_lossy(&self.src[start..self.pos]).into_owned()
    }

    fn parse_key_value(&mut self) -> PResult<(Vec<String>, Value)> {
        let path = self.parse_key_path()?;
        self.skip_ws();
        if !self.eat(b'=') {
            return Err(ParseError);
        }
        self.skip_ws();
        let value = self.parse_value()?;
        Ok((path, value))
    }

    fn parse_value(&mut self) -> PResult<Value> {
        match self.peek() {
            None => Err(ParseError),
            Some(b'"') => {
                if self.starts_with(b"\"\"\"") {
                    self.pos += 3;
                    self.parse_multiline_basic_string().map(Value::Str)
                } else {
                    self.pos += 1;
                    self.parse_basic_string_body().map(Value::Str)
                }
            }
            Some(b'\'') => {
                if self.starts_with(b"'''") {
                    self.pos += 3;
                    self.parse_multiline_literal_string().map(Value::Str)
                } else {
                    self.pos += 1;
                    self.parse_literal_string_body().map(Value::Str)
                }
            }
            Some(b'[') => self.parse_array(),
            Some(b'{') => self.parse_inline_table(),
            Some(b'+') => {
                self.pos += 1;
                let start = self.pos;
                let token = self.take_keylike();
                if token.is_empty() {
                    return Err(ParseError);
                }
                self.parse_number(start, &token)
            }
            Some(c) if is_bare_key_char(c) => {
                let start = self.pos;
                let token = self.take_keylike();
                match token.as_str() {
                    "true" => Ok(Value::Bool(true)),
                    "false" => Ok(Value::Bool(false)),
                    _ => self.parse_number_or_datetime(start, &token),
                }
            }
            Some(_) => Err(ParseError),
        }
    }

    fn parse_array(&mut self) -> PResult<Value> {
        // assumes current char is '['
        self.pos += 1;
        let mut items = Vec::new();
        loop {
            self.skip_ws_comments_newlines()?;
            if self.eat(b']') {
                break;
            }
            let v = self.parse_value()?;
            items.push(v);
            self.skip_ws_comments_newlines()?;
            if self.eat(b',') {
                continue;
            }
            self.skip_ws_comments_newlines()?;
            if self.eat(b']') {
                break;
            }
            return Err(ParseError);
        }
        Ok(Value::Array(items))
    }

    fn parse_inline_table(&mut self) -> PResult<Value> {
        self.pos += 1;
        let mut table = Table::new();
        self.skip_ws();
        if self.eat(b'}') {
            return Ok(Value::Table(table));
        }
        loop {
            self.skip_ws();
            let (path, value) = self.parse_key_value()?;
            insert_dotted(&mut table, &path, value)?;
            self.skip_ws();
            if self.eat(b',') {
                continue;
            }
            if self.eat(b'}') {
                break;
            }
            return Err(ParseError);
        }
        Ok(Value::Table(table))
    }

    fn parse_escape(&mut self, out: &mut String) -> PResult<()> {
        // after backslash
        match self.bump() {
            Some(b'b') => out.push('\u{8}'),
            Some(b't') => out.push('\t'),
            Some(b'n') => out.push('\n'),
            Some(b'f') => out.push('\u{c}'),
            Some(b'r') => out.push('\r'),
            Some(b'"') => out.push('"'),
            Some(b'\\') => out.push('\\'),
            Some(b'u') => {
                let cp = self.parse_hex(4)?;
                out.push(char::from_u32(cp).ok_or(ParseError)?);
            }
            Some(b'U') => {
                let cp = self.parse_hex(8)?;
                out.push(char::from_u32(cp).ok_or(ParseError)?);
            }
            _ => return Err(ParseError),
        }
        Ok(())
    }

    fn parse_hex(&mut self, n: usize) -> PResult<u32> {
        let mut v: u32 = 0;
        for _ in 0..n {
            let c = self.bump().ok_or(ParseError)?;
            let d = (c as char).to_digit(16).ok_or(ParseError)?;
            v = v.checked_mul(16).ok_or(ParseError)? + d;
        }
        Ok(v)
    }

    fn take_utf8_char(&mut self, out: &mut String) -> PResult<()> {
        let rest = &self.src[self.pos..];
        let s = std::str::from_utf8(&rest[..rest.len().min(4)])
            .or_else(|e| std::str::from_utf8(&rest[..e.valid_up_to()]))
            .map_err(|_| ParseError)?;
        let ch = s.chars().next().ok_or(ParseError)?;
        out.push(ch);
        self.pos += ch.len_utf8();
        Ok(())
    }

    fn parse_basic_string_body(&mut self) -> PResult<String> {
        let mut out = String::new();
        loop {
            match self.peek() {
                None => return Err(ParseError),
                Some(b'"') => {
                    self.pos += 1;
                    return Ok(out);
                }
                Some(b'\\') => {
                    self.pos += 1;
                    self.parse_escape(&mut out)?;
                }
                Some(b'\n') => return Err(ParseError),
                Some(c) if c < 0x20 && c != b'\t' => return Err(ParseError),
                Some(0x7f) => return Err(ParseError),
                Some(_) => self.take_utf8_char(&mut out)?,
            }
        }
    }

    fn parse_multiline_basic_string(&mut self) -> PResult<String> {
        let mut out = String::new();
        // trim first newline
        if self.eat(b'\n') {
        } else if self.starts_with(b"\r\n") {
            self.pos += 2;
        }
        loop {
            match self.peek() {
                None => return Err(ParseError),
                Some(b'"') => {
                    if self.starts_with(b"\"\"\"") {
                        self.pos += 3;
                        // up to two additional quotes belong to the content
                        let mut extra = 0;
                        while self.peek() == Some(b'"') && extra < 2 {
                            out.push('"');
                            self.pos += 1;
                            extra += 1;
                        }
                        if self.peek() == Some(b'"') {
                            return Err(ParseError);
                        }
                        return Ok(out);
                    }
                    out.push('"');
                    self.pos += 1;
                }
                Some(b'\\') => {
                    self.pos += 1;
                    // line ending backslash
                    let save = self.pos;
                    self.skip_ws();
                    if self.peek() == Some(b'\n') || self.starts_with(b"\r\n") {
                        self.skip_ws_newlines_only();
                    } else {
                        self.pos = save;
                        self.parse_escape(&mut out)?;
                    }
                }
                Some(b'\r') if self.peek_at(1) == Some(b'\n') => {
                    out.push('\n');
                    self.pos += 2;
                }
                Some(b'\n') => {
                    out.push('\n');
                    self.pos += 1;
                }
                Some(c) if c < 0x20 && c != b'\t' => return Err(ParseError),
                Some(0x7f) => return Err(ParseError),
                Some(_) => self.take_utf8_char(&mut out)?,
            }
        }
    }

    fn skip_ws_newlines_only(&mut self) {
        while let Some(c) = self.peek() {
            if c == b' ' || c == b'\t' || c == b'\n' || c == b'\r' {
                self.pos += 1;
            } else {
                break;
            }
        }
    }

    fn parse_literal_string_body(&mut self) -> PResult<String> {
        let mut out = String::new();
        loop {
            match self.peek() {
                None => return Err(ParseError),
                Some(b'\'') => {
                    self.pos += 1;
                    return Ok(out);
                }
                Some(b'\n') => return Err(ParseError),
                Some(c) if c < 0x20 && c != b'\t' => return Err(ParseError),
                Some(0x7f) => return Err(ParseError),
                Some(_) => self.take_utf8_char(&mut out)?,
            }
        }
    }

    fn parse_multiline_literal_string(&mut self) -> PResult<String> {
        let mut out = String::new();
        if self.eat(b'\n') {
        } else if self.starts_with(b"\r\n") {
            self.pos += 2;
        }
        loop {
            match self.peek() {
                None => return Err(ParseError),
                Some(b'\'') => {
                    if self.starts_with(b"'''") {
                        self.pos += 3;
                        let mut extra = 0;
                        while self.peek() == Some(b'\'') && extra < 2 {
                            out.push('\'');
                            self.pos += 1;
                            extra += 1;
                        }
                        if self.peek() == Some(b'\'') {
                            return Err(ParseError);
                        }
                        return Ok(out);
                    }
                    out.push('\'');
                    self.pos += 1;
                }
                Some(b'\r') if self.peek_at(1) == Some(b'\n') => {
                    out.push('\n');
                    self.pos += 2;
                }
                Some(b'\n') => {
                    out.push('\n');
                    self.pos += 1;
                }
                Some(c) if c < 0x20 && c != b'\t' => return Err(ParseError),
                Some(0x7f) => return Err(ParseError),
                Some(_) => self.take_utf8_char(&mut out)?,
            }
        }
    }

    /// Consume a mandatory keylike token (used by date/time parsing).
    fn expect_keylike(&mut self) -> PResult<()> {
        let token = self.take_keylike();
        if token.is_empty() {
            return Err(ParseError);
        }
        Ok(())
    }

    /// Date and time literals are consumed token-wise and kept verbatim.
    fn parse_datetime(&mut self, start: usize, colon_eaten: bool) -> PResult<Value> {
        // space separated date and time
        if self.peek() == Some(b' ')
            && self.peek_at(1).map_or(false, is_bare_key_char)
            && !(self.peek_at(1) == Some(b' ') || self.peek_at(1) == Some(b'\t'))
        {
            self.pos += 1;
            self.take_keylike();
        }
        if colon_eaten || self.eat(b':') {
            self.expect_keylike()?;
            if !self.eat(b':') {
                return Err(ParseError);
            }
            self.expect_keylike()?;
            if self.eat(b'.') {
                self.expect_keylike()?;
            }
            if self.eat(b'+') {
                self.expect_keylike()?;
            }
            if self.eat(b':') {
                self.expect_keylike()?;
            }
        }
        let raw = String::from_utf8_lossy(&self.src[start..self.pos]).into_owned();
        Ok(Value::Datetime(raw))
    }

    fn parse_number_or_datetime(&mut self, start: usize, token: &str) -> PResult<Value> {
        let looks_like_date = token.contains('T')
            || token.contains('t')
            || (token.len() > 1
                && token[1..].contains('-')
                && !token.contains("e-")
                && !token.contains("E-"));
        if looks_like_date {
            return self.parse_datetime(start, false);
        }
        if self.eat(b':') {
            return self.parse_datetime(start, true);
        }
        self.parse_number(start, token)
    }

    fn parse_number(&mut self, _start: usize, token: &str) -> PResult<Value> {
        if let Some(rest) = token.strip_prefix("0x") {
            return parse_integer(rest, 16).map(Value::Int);
        }
        if let Some(rest) = token.strip_prefix("0o") {
            return parse_integer(rest, 8).map(Value::Int);
        }
        if let Some(rest) = token.strip_prefix("0b") {
            return parse_integer(rest, 2).map(Value::Int);
        }
        if token.contains('e') || token.contains('E') {
            return self.parse_float(token, None).map(Value::Float);
        }
        if self.eat(b'.') {
            let after = self.take_keylike();
            if after.is_empty() {
                return Err(ParseError);
            }
            return self.parse_float(token, Some(&after)).map(Value::Float);
        }
        match token {
            "inf" | "+inf" => return Ok(Value::Float(f64::INFINITY)),
            "-inf" => return Ok(Value::Float(f64::NEG_INFINITY)),
            "nan" | "+nan" | "-nan" => return Ok(Value::Float(f64::NAN)),
            _ => {}
        }
        parse_integer(token, 10).map(Value::Int)
    }

    fn parse_float(&mut self, token: &str, after_decimal: Option<&str>) -> PResult<f64> {
        let (integral, mut suffix) = split_integer(token, true, false, 10)?;
        let mut fraction: Option<&str> = None;
        if let Some(after) = after_decimal {
            if !suffix.is_empty() {
                return Err(ParseError);
            }
            let (a, b) = split_integer(after, false, true, 10)?;
            fraction = Some(a);
            suffix = b;
        }
        let mut exponent: Option<String> = None;
        if suffix.starts_with('e') || suffix.starts_with('E') {
            if suffix.len() == 1 {
                self.eat(b'+');
                let digits = self.take_keylike();
                if digits.is_empty() {
                    return Err(ParseError);
                }
                let (a, b) = split_integer(&digits, false, false, 10)?;
                if !b.is_empty() {
                    return Err(ParseError);
                }
                exponent = Some(a.to_string());
            } else {
                let (a, b) = split_integer(&suffix[1..], true, false, 10)?;
                if !b.is_empty() {
                    return Err(ParseError);
                }
                exponent = Some(a.to_string());
            }
        } else if !suffix.is_empty() {
            return Err(ParseError);
        }
        let mut number: String = integral
            .trim_start_matches('+')
            .chars()
            .filter(|c| *c != '_')
            .collect();
        if let Some(fraction) = fraction {
            number.push('.');
            number.extend(fraction.chars().filter(|c| *c != '_'));
        }
        if let Some(exponent) = exponent {
            number.push('E');
            number.extend(exponent.chars().filter(|c| *c != '_'));
        }
        let value: f64 = number.parse().map_err(|_| ParseError)?;
        if value.is_finite() {
            Ok(value)
        } else {
            Err(ParseError)
        }
    }
}

/// Split `s` into the leading integer part and the remaining suffix,
/// validating sign, leading zeros and underscores.
fn split_integer(
    s: &str,
    allow_sign: bool,
    allow_leading_zeros: bool,
    radix: u32,
) -> PResult<(&str, &str)> {
    let mut first = true;
    let mut first_zero = false;
    let mut underscore = false;
    let mut end = s.len();
    for (i, c) in s.char_indices() {
        if i == 0 && (c == '+' || c == '-') && allow_sign {
            continue;
        }
        if c == '0' && first {
            first_zero = true;
        } else if c.is_digit(radix) {
            if !first && first_zero && !allow_leading_zeros {
                return Err(ParseError);
            }
            underscore = false;
        } else if c == '_' && first {
            return Err(ParseError);
        } else if c == '_' && !underscore {
            underscore = true;
        } else {
            end = i;
            break;
        }
        first = false;
    }
    if first || underscore {
        return Err(ParseError);
    }
    Ok((&s[..end], &s[end..]))
}

fn parse_integer(s: &str, radix: u32) -> PResult<i64> {
    let allow_sign = radix == 10;
    let allow_leading_zeros = radix != 10;
    let (prefix, suffix) = split_integer(s, allow_sign, allow_leading_zeros, radix)?;
    if !suffix.is_empty() {
        return Err(ParseError);
    }
    let cleaned = prefix.replace('_', "");
    i64::from_str_radix(cleaned.trim_start_matches('+'), radix).map_err(|_| ParseError)
}

