use std::path::{Path, PathBuf};

use crate::toml::{self, SerError, Table};

/// Types that can be loaded from / stored into a TOML file.
pub trait FileIO: Sized {
    /// Build the object from a parsed TOML table.
    fn from_table(table: &Table) -> Option<Self>;

    /// Turn the object into a TOML table (fails on non UTF-8 paths).
    fn to_table(&self) -> Result<Table, SerError>;

    /// Default content used when the file does not exist yet.
    fn default_value() -> Self;

    /// Parse the textual representation of the data file.
    fn parse(data: &str) -> Self {
        let table = toml::parse(data).ok();
        let parsed_data = table.and_then(|t| Self::from_table(&t));
        parsed_data.expect("couldn't parse data")
    }

    /// Read a data file; `None` when it does not exist.
    fn read(path: &Path) -> Option<String> {
        let file_contents = read_or_missing(path);
        file_contents.expect("couldn't load file")
    }

    /// Serialize the object to TOML text.
    fn serialize(&self) -> Result<String, SerError> {
        Ok(toml::to_string(&self.to_table()?))
    }

    /// Open the data file for writing, truncating any previous content.
    fn open_for_write(path: &Path) -> fs::File {
        fs::File::create(path)
            .unwrap()
    }

    fn load(path: &Path) -> Self {
        let Some(data) = Self::read(path) else {
            fs::create_dir_all(&dirname(path)).unwrap();
            let defaults_table = Self::default_value().to_table().unwrap_or_default();
            fs::write(path, toml::to_string(&defaults_table).into_bytes()).unwrap();
            return Self::default_value();
        };
        Self::parse(&data)
    }

    /// Write the object to `path` (the parent folder must exist).
    fn store(&self, path: &Path) {
        let mut file = Self::open_for_write(path);
        file.write_all(toml::to_string(&self.to_table().unwrap()).as_bytes())
            .unwrap();
    }
}

/// Contents of the file at `path`: `Some(None)` when the file is missing,
/// `None` when it exists but cannot be read.
fn read_or_missing(path: &Path) -> Option<Option<String>> {
    match fs::read_to_string(path) {
        Ok(data) => Some(Some(data)),
        Err(err) if err.kind() == std::io::ErrorKind::NotFound => Some(None),
        Err(_) => None,
    }
}

/// Folder containing `path`.
fn dirname(path: &Path) -> PathBuf {
    path.parent().unwrap_or(Path::new("")).to_path_buf()
}
