// ---------------------------------------------------------------------------
// Path helpers
// ---------------------------------------------------------------------------

/// Resolve `target` relative to `base` and make sure the result stays
/// inside `root`.
///
/// The target must exist (`PathNotFound` otherwise); symbolic links are
/// resolved before checking the bounds (`OutOfBounds` when the resolved
/// path is not inside `root`). Returns the joined path, its canonical form
/// and the canonical form relative to `root`.
pub fn resolve_within(base: &Path, target: &Path, root: &Path) -> Result<(PathBuf, PathBuf, PathBuf)> {
    let joined = base.join(target);
    if !joined.exists() {
        return Err(Error::PathNotFound);
    }
    let canonical = joined.canonicalize()?;
    let relative = match canonical.strip_prefix(root) {
        Ok(relative) => relative.to_path_buf(),
        Err(_) => return Err(Error::OutOfBounds),
    };
    Ok((joined, canonical, relative))
}

/// Textual form of a path, normalized component by component (so that
/// `a/./b//c` becomes `a/b/c`).
///
/// Panics when the path is not valid UTF-8, as such paths cannot be stored
/// in the TOML data files anyway.
pub fn path_string(path: &Path) -> String {
    path.components().collect::<PathBuf>().to_str().unwrap().to_string()
}
